public class CirculationReport { static class Member{String course;Member(String c){course=c;}void displayInfo(){System.out.print("General | Books: 0 | ");}} static class Student extends Member{Student(String c){super(c);}@Override void displayInfo(){System.out.print("Student | Course: "+course+" | Books: 0 | ");}} static String batchPrint(Member[]a){StringBuilder s=new StringBuilder();for(Member m:a){m.displayInfo();s.append(m instanceof Student?"Student":"General").append(" | ");}return s.toString();} public static void main(String[]x){System.out.println(batchPrint(new Member[]{new Member(""),new Student("ECE")}));}}
